/**
 * browser-polyfill stub — LoveSpark Reader
 * Chrome MV3 uses chrome.* APIs natively; this is a no-op shim.
 * Replace with the real Mozilla WebExtension Polyfill for Firefox:
 *   https://github.com/mozilla/webextension-polyfill
 */
(function () {
  'use strict';
  if (typeof globalThis.browser === 'undefined') {
    globalThis.browser = globalThis.chrome;
  }
})();
